//! Lua templates, copied verbatim from the Python reference (eilmer_mesher/lua/codegen.py,
//! eilmer_mesher/model/bcs.py).

pub const HEADER: &str = r#"-- mesh.lua
-- Generated by eilmer-mesher. Edit the .emesh.json project, not this file.
--   lmr prep-grids -j mesh.lua      registers the grids for a simulation
--   lmr custom-script -j mesh.lua   writes {preview}/blk-NNNN.vtk for the GUI
if config then config.dimensions = 2 end
"#;

pub const LAPLACE_HELPER: &str = r#"function laplaceSmooth(grid, nsweeps, tol)
   local niv, njv = grid:get_niv(), grid:get_njv()
   local xo, yo, xn, yn = {}, {}, {}, {}
   for i = 0, niv-1 do
      xo[i], yo[i], xn[i], yn[i] = {}, {}, {}, {}
      for j = 0, njv-1 do
         local v = grid:get_vtx(i, j)
         xo[i][j], yo[i][j], xn[i][j], yn[i][j] = v.x, v.y, v.x, v.y
      end
   end
   for n = 1, nsweeps do
      local maxChange = 0.0
      for i = 1, niv-2 do
         for j = 1, njv-2 do
            local x = 0.25*(xo[i+1][j] + xo[i-1][j] + xo[i][j+1] + xo[i][j-1])
            local y = 0.25*(yo[i+1][j] + yo[i-1][j] + yo[i][j+1] + yo[i][j-1])
            maxChange = math.max(maxChange, math.abs(x - xo[i][j]), math.abs(y - yo[i][j]))
            xn[i][j], yn[i][j] = x, y
         end
      end
      xo, xn = xn, xo
      yo, yn = yn, yo
      if maxChange < tol then break end
   end
   for i = 1, niv-2 do
      for j = 1, njv-2 do
         grid:set_vtx(i, j, Vector3:new{x=xo[i][j], y=yo[i][j]})
      end
   end
end
"#;

pub const GROWTH_HELPER: &str = r#"growthClusterCount = 0
function growthCluster(r, ncells, reverse)
   growthClusterCount = growthClusterCount + 1
   local name = string.format("growthCluster%d", growthClusterCount)
   local R = r^ncells
   _G[name] = function(t)
      if reverse then t = 1.0 - t end
      local x = (R^t - 1.0)/(R - 1.0)
      if reverse then x = 1.0 - x end
      return x
   end
   return LuaFnClustering:new{luaFnName=name}
end

-- Vertex positions given as a table (0..1), linear in between.
function tableCluster(x)
   growthClusterCount = growthClusterCount + 1
   local name = string.format("growthCluster%d", growthClusterCount)
   local n = #x - 1
   _G[name] = function(t)
      local u = t*n
      local k = math.floor(u)
      if k >= n then return x[n+1] end
      if k < 0 then return x[1] end
      return x[k+1] + (u - k)*(x[k+2] - x[k+1])
   end
   return LuaFnClustering:new{luaFnName=name}
end
"#;

pub const FOOTER: &str = r#"if registerFluidGrid then
   -- lmr prep-grids
   local ids = {}
   for i, b in ipairs(blocks) do
      ids[i] = registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   -- Blocks are joined only across block split lines; a solid curve between
   -- two blocks stays a wall on both sides.
{connections}
else
   -- lmr custom-script: preview output for the GUI
   os.execute("mkdir -p {preview}")
   for i, b in ipairs(blocks) do
      b.grid:write_to_vtk_file(string.format("{preview}/blk-%04d.vtk", i-1))
   end
end
"#;

pub const SIM_TEMPLATE: &str = r#"-- sim.lua: a starting point for simulating the grids exported by eilmer-mesher.
-- Edit the gas model, flow states and run settings, then:
--   lmr prep-gas -i ideal-air.lua -o ideal-air.gas   (or use your own gas file)
--   lmr prep-grids -j mesh.lua
--   lmr prep-sim -j sim.lua
--   lmr run
--   lmr snapshot2vtk -a
--   cd lmrsim/vtk && paraview fluid.pvd
setGasModel("ideal-air.gas")
config.solver_mode = "transient"
config.gasdynamic_update_scheme  = "predictor-corrector"
config.flux_calculator = "adaptive_hanel_ausmdv"
config.dimensions = 2
config.axisymmetric = false

-- Flow states. 'initial' fills the domain (every block has fsTag "initial");
-- the others are referred to by the boundary conditions in bcs.lua.
p_inf = 1.5e3 -- Pa
T_inf = 227.0 -- K
M_inf = 6.0
tmp = FlowState:new{{p=p_inf, T=T_inf}}
u_inf = M_inf * tmp.a -- m/s

initial = FlowState:new{{p=p_inf/5.0, T=T_inf}}          -- used by all blocks (fsTag="initial")
{states}

flowDict = {{{flowdict}}}

dofile("bcs.lua")               -- bcDict: the boundary-condition tags set in the GUI
makeFluidBlocks(bcDict, flowDict)

config.max_time = 1e-3          -- seconds
config.max_step = 100000
config.dt_init = 1.0e-9
config.cfl_value = 0.5
config.dt_plot = config.max_time / 100
"#;

pub const GAS_TEMPLATE: &str = r#"-- ideal-air.lua: gas model input for `lmr prep-gas -i ideal-air.lua -o ideal-air.gas`
model = "IdealGas"
species = {'air'}
"#;
